import sys
from collections import defaultdict

def longestString(arr):
    arr.sort()
    prefix_set = set()
    longest = ""

    for s in arr:
        if all(s[:i] in prefix_set for i in range(1, len(s))):
            if len(s) > len(longest):
                longest = s
        prefix_set.add(s)

    return longest

def main():
    input = sys.stdin.read().strip().split()
    result = longestString(input)
    print(result)

if __name__ == "__main__":
    main()
